#[derive(Debug, Clone, PartialEq)]
pub struct ItemFireworkExplosion {
    pub shape: ItemFireworkExplosionShape,
    pub colors: Vec<i32>,
    pub fade_colors: Vec<i32>,
    pub has_trail: bool,
    pub has_twinkle: bool,
}

impl crate::traits::Encode for ItemFireworkExplosion {
    fn encode(&self, out: &mut crate::buffer::PacketWriter) -> crate::error::Result<()> {
        crate::traits::Encode::encode(&self.shape, out)?;
        out.put_varint((self.colors).len() as i32);
        for item in &self.colors {
        out.put_i32(*item);
        }
        out.put_varint((self.fade_colors).len() as i32);
        for item in &self.fade_colors {
        out.put_i32(*item);
        }
        crate::traits::Encode::encode(&self.has_trail, out)?;
        crate::traits::Encode::encode(&self.has_twinkle, out)?;
        Ok(())
    }
}

impl crate::traits::Decode for ItemFireworkExplosion {
    fn decode(input: &mut crate::buffer::PacketReader<'_>) -> crate::error::Result<Self> {
        let shape = <ItemFireworkExplosionShape as crate::traits::Decode>::decode(input)?;
        let colors = input.read_array(|input| { Ok(input.get_i32()?) })?;
        let fade_colors = input.read_array(|input| { Ok(input.get_i32()?) })?;
        let has_trail = <bool as crate::traits::Decode>::decode(input)?;
        let has_twinkle = <bool as crate::traits::Decode>::decode(input)?;
        Ok(Self { shape, colors, fade_colors, has_trail, has_twinkle })
    }
}

