#[derive(Debug, Clone, PartialEq)]
pub enum PreviousMessagesItemSignature {
    V0(Vec<u8>),
    Default,
}

impl crate::traits::Encode for PreviousMessagesItemSignature {
    fn encode(&self, out: &mut crate::buffer::PacketWriter) -> crate::error::Result<()> {
        match self {
            Self::V0(v) => {
                if (*v).len() != 256 { return Err(crate::error::ProtocolError::InvalidData(format!("type `previousMessages`.signature: expected exactly 256 bytes"))); }
                out.put_bytes(&*v);
            }
            Self::Default => {}
        }
        Ok(())
    }
}

impl PreviousMessagesItemSignature {
    pub fn decode_from(
        input: &mut crate::buffer::PacketReader<'_>,
        discriminant: i32,
    ) -> crate::error::Result<Self> {
        match discriminant {
            0 => Ok(Self::V0(input.read_bytes(256)?.to_vec())),
            _ => Ok(Self::Default),
        }
    }
}

